# Import required modules
import tkinter as tk

# Define the Game class
class Game:
    def __init__(self, board):
        # Initialize the game's attributes
        self.board = board
        self.running = False
        self.previousState = None

    def updateState(self):
        # Update the game's state
        newBoardState = [[False] * self.board.cols for row in range(self.board.rows)]
        for row in range(self.board.rows):
            for col in range(self.board.cols):
                liveNeighbors = self.countLiveNeighbors(row, col)
                cellAlive = self.board.state[row][col]
                if cellAlive and 2 <= liveNeighbors <= 3:
                    newBoardState[row][col] = True
                elif not cellAlive and liveNeighbors == 3:
                    newBoardState[row][col] = True
        self.previousState = self.board.state
        self.board.state = newBoardState

    def countLiveNeighbors(self, row, col):
        # Count the number of live neighbors of the cell at the specified coordinates
        count = 0
        for r in range(-1, 2):
            for c in range(-1, 2):
                if (r != 0 or c != 0) and 0 <= row + r < self.board.rows and 0 <= col + c < self.board.cols:
                    count += self.board.state[row + r][col + c]
        return count

    def reset(self):
        # Reset the game's state
        self.running = False
        self.board.initializeState()

    def isSteadyState(self):
        # Check if the game has reached a steady state
        if self.previousState is None:
            return False
        for row in range(self.board.rows):
            for col in range(self.board.cols):
                if self.previousState[row][col] != self.board.state[row][col]:
                    return False
        return True
