        newGrid = [[0 for _ in range(cols)] for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                neighbors = self.countNeighbors(i, j)
                if self.grid[i][j] and (neighbors == 2 or neighbors == 3):
                    newGrid[i][j] = 1
                elif not self.grid[i][j] and neighbors == 3:
