Here is a sample code for generating a few ADPCM tables:
```c
#include <stdio.h>

const int TABLE_SIZE = 1024;

int main() {
    int i, j, step = 2;
    float table[TABLE_SIZE][2];

    // Initialize the table with audio data
    for (i = 0; i < TABLE_SIZE; i++) {
        table[i][0] = i / (float) step;
        table[i][1] = (1.0 / (2.0 * (i % 2 == 0 ? 1.0 : -1.0))) * 32767.0;
    }

    // Normalize the audio data
    for (i = 1; i < TABLE_SIZE - 1; i++) {
        table[i][1] = table[i][1] / table[i - 1][1];
    }

    // Print the audio data table for debugging purposes
    for (i = 0; i < TABLE_SIZE; i++) {
        printf("(%f, %f)\n", table[i][0], table[i][1]);
    }

    return 0;
}
```
This code generates a 1024-point ADPCM table with a step size of 2. The audio data is normalized so that the maximum amplitude is 32767. The table is printed to the console for debugging purposes.

