```python
import tkinter as tk
import random
import sys

class Labyrinth:
    def initialize_labyrinth(self, width, height):
        self.width = width
        self.height = height
        self.grid = [['#' for _ in range(width)] for _ in range(height)]

    def carve_path(self, x, y):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        random.shuffle(directions)
        for dx, dy in directions:
            nx, ny = x + dx * 2, y + dy * 2
            if 0 <= nx < self.width and 0 <= ny < self.height and self.grid[ny][nx] == '#':
                self.grid[y + dy][x + dx] = ' '
                self.grid[ny][nx] = ' '
                self.carve_path(nx, ny)

    def display_labyrinth(self):
        self.root = tk.Tk()
        self.canvas = tk.Canvas(self.root, width=self.width * 10, height=self.height * 10, bg='white')
        self.canvas.pack()
        for y, row in enumerate(self.grid):
            for x, cell in enumerate(row):
                if cell == '#':
                    self.canvas.create_rectangle(x * 10, y * 10, (x + 1) * 10, (y + 1) * 10, fill='black')
        self.root.mainloop()

    def is_valid_move(self, x, y):
        return 0 <= x < self.width and 0 <= y < self.height and self.grid[y][x] == ' '

    def solve_labyrinth(self, x, y, visited=None):
        if not self.is_valid_move(x, y) or (visited and (x, y) in visited):
            return None
        if x == self.width - 2 and y == self.height - 2:
            return [(x, y)]
        visited = visited or set()
        visited.add((x, y))
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            path = self.solve_labyrinth(x + dx, y + dy, visited)
            if path:
                return [(x, y)] + path
        return None

    def highlight_solution(self, solution):
        for x, y in solution:
            self.canvas.create_rectangle(x * 10, y * 10, (x + 1) * 10, (y + 1) * 10, fill='red')
        self.root.update()

def main():
    labyrinth = Labyrinth()
    labyrinth.initialize_labyrinth(31, 31)
    labyrinth.carve_path(1, 1)
    solution = labyrinth.solve_labyrinth(1, 1)
    labyrinth.display_labyrinth()
    if solution:
        labyrinth.highlight_solution(solution)

if __name__ == "__main__":
    main()
```

