Here is a Python program that solves a Sudoku puzzle by filling the empty cells:

```python
import itertools

def sudoku(board):
    # Check if the board is valid
    rows = [set(row) for row in board]
    cols = [set(col) for col in zip(*board)]
    boxes = [set(row) for row in zip(*board)]
    if len(rows) != len(cols) != len(boxes):
        return None
    for row in rows:
        for col in cols:
            if len(row.intersection(col)) > 1:
                return None
    for box in boxes:
        if len(box) != 3:
            return None
    # If the board is valid, we can fill in the empty cells using brute force
    filled = [False] * 9
    for i in range(9):
        for j in range(9):
            if board[i][j] == ".":
                for k in range(9):
                    if not filled[k]:
                        board[i][j] = k + 1
                        filled[k] = True
                        for row in rows:
                            for col in cols:
                                if (k == row[i]) or (k == col[i]):
                                    board[row.index(row[i])][col.index(col[i])] = "."
                                    filled[k] = False
                                    break
                                elif (k == row[j]) or (k == col[j]):
                                    board[row.index(row[j])][col.index(col[j])] = "."
                                    filled[k] = False
                                    break
                        for box in boxes:
                            if k in box:
                                board[box.index(k)][box.index(k)] = "."
                                filled[k] = False
    return board

