In OpenCV for C#, you can use the `IplImage` class to represent a single image. This class is part of the OpenCV library and provides methods for performing image processing operations on a single image.

Here is an example of how to use the `IplImage` class in C#:
```csharp
using System;
using System.Runtime.InteropServices;
using OpenCv;

class Program
{
    [DllImport("opencv4.dll")]
    private static extern IntPtr cvLoadImage(string filename);

    [DllImport("opencv4.dll")]
    private static extern IntPtr cvCreateMatHeader(int rows, int cols, int type, IntPtr data);

    [DllImport("opencv4.dll")]
    private static extern void cvReleaseImage(IntPtr image);

    public static void Main(string[] args)
    {
        // Load the image
        IntPtr image = cvLoadImage("path/to/image.jpg");

        // Create an IplImage object
        IplImage iplImage = new IplImage(image);

        // Save the image
        image = cvCreateMatHeader(iplImage.Rows, iplImage.Cols, (int)iplImage.Depth, iplImage.Data);
        cvReleaseImage(image);
    }
}
