class GameOfLifeGrid:
    def __init__(self, width, height, cell_size, canvas):
        self.width = width
        self.height = height
        self.cell_size = cell_size
        self.canvas = canvas
        self.cells = [[False for y in range(height)] for x in range(width)]
        self.rectangles = [[self.canvas.create_rectangle(x * cell_size, y * cell_size, (x + 1) * cell_size, (y + 1) * cell_size, fill="#000000") for y in range(height)] for x in range(width)]

    def set_cell(self, pos, value):
        self.cells[pos[0]][pos[1]] = value
        color = "#FFFFFF" if value else "#000000"
        self.canvas.itemconfig(self.rectangles[pos[0]][pos[1]], fill=color)

    def get_cell(self, pos):
        if pos[0] < 0 or pos[0] >= self.width or pos[1] < 0 or pos[1] >= self.height:
            return False
        return self.cells[pos[0]][pos[1]]

    def update(self):
        new_cells = [[False for y in range(self.height)] for x in range(self.width)]

        for x in range(self.width):
            for y in range(self.height):
                count = self.get_neighbor_count((x, y))

                if self.cells[x][y]:
                    if count == 2 or count == 3:
                        new_cells[x][y] = True
                else:
                    if count == 3:
                        new_cells[x][y] = True

        self.cells = new_cells

        for x in range(self.width):
            for y in range(self.height):
                color = "#FFFFFF" if self.cells[x][y] else "#000000"
                self.canvas.itemconfig(self.rectangles[x][y], fill=color)

    def get_neighbor_count(self, pos):
        count = 0

        for x in range(pos[0] - 1, pos[0] + 2):
            for y in range(pos[1] - 1, pos[1] + 2):
                if (x, y) != pos and self.get_cell((x, y)):
                    count += 1

        return count
```

