var callback: () -> Void = {
    print("Callback called!") 
}

func doSomething(completion: () -> Void) {
    completion()
}

doSomething(callback) 
// Prints "Callback called!"
```

The `doSomething(completion:)` function accepts a callback closure which is executed at the end of the function.

