import sys
import re

def parse_input():
    # Read the initialization data from standard input
    width = int(sys.stdin.readline())
    height = int(sys.stdin.readline())

    # Initialize the grid with empty cells
    grid = [['.' for _ in range(width)] for _ in range(height)]

    # Read the next height lines of the input
    for i in range(height):
        line = sys.stdin.readline().strip()
        updates = re.findall(r'[01]\d+', line)
        for pos, value in updates:
            if value == '0':
                grid[i][pos-1] = (0, 0) # NAME_1
            elif value == '1':
                grid[i][pos-1] = (1, 1) # Wall

    return grid, height

