        Calculate the log-likelihood of the given sequence x.
        """
        scores = self.forward_pass(x)
        return np.sum(scores)

    def forward_pass(self, x):
        """
        Calculate the forward pass of the CRF.
        """
        y = np.zeros(self.V)
        for v in self.V:
            for e in self.E:
                if e[0] == v and e[1] in x:
                    y[v] += self.weights[v, e[1], e[2]] * x[e[1]]
