    def backward_pass(self, grad):
        """
        Calculate the backward pass of the CRF.
        """
        for v in self.V:
            for e in self.E:
                if e[0] == v:
                    self.weights[v, e[1], e[2]] += grad[v] * (1 - (e[2] in x))

