function time_since(date: string | Date)
{
    if (typeof (date) === "string") date = new Date(date);

    let seconds = Math.floor((new Date().getTime() - date.getTime()) / 1000);

    let interval = Math.floor(seconds / 31536000);
    if (interval > 0) return interval + " years";

    interval = Math.floor(seconds / 2592000);
    if (interval > 0) return interval + " months";

    interval = Math.floor(seconds / 86400);
    if (interval > 0) return interval + " days";

    interval = Math.floor(seconds / 3600);
    if (interval > 0) return interval + " hours";

    interval = Math.floor(seconds / 60);
    if (interval > 0) return interval + " minutes";

    return Math.floor(seconds) + " seconds";
}

enum ECtfState {
    Upcoming,
    Running,
    Ended,
}

function get_ctf_state(startDate: string | Date, endDate: string | Date) : ECtfState
{
    if (typeof (startDate) === "string") startDate = new Date(startDate);
    if (typeof (endDate) === "string") endDate = new Date(endDate);

    const now = new Date();
    if (now < startDate) return ECtfState.Upcoming;
    if (now > endDate) return ECtfState.Ended;
    return ECtfState.Running;
}

export default {
    time_since,
    get_ctf_state
}

