```c
#include <stdio.h>
#include <math.h>

double geometric_mean(double *arr, int n) {
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum *= arr[i];
    }
    return pow(sum, 1.0 / n);
}

int main() {
    double arr[] = {1, 2, 3, 4, 5};
    int n = sizeof(arr) / sizeof(arr[0]);
    double mean = geometric_mean(arr, n);
