```python
def count_neighbors(matrix, distance):
    n = matrix.shape[0]
    m = matrix.shape[1]
    count = 0
    for i in range(n):
        for j in range(m):
            # Count neighbors within distance
            if i > 0:
                matrix[i-1][j]
            if j > 0:
                matrix[i][j-1]
            if i < n-1:
                matrix[i+1][j]
            if j < m-1:
                matrix[i][j+1]
            if abs(i-j) <= distance:
                count += 1
    return count
```
