def answer(N, M, queries):
    # Create a dictionary to store the cost of changing each element to its corresponding query value
    cost = {}

    # Iterate over the queries and for each query, find the cost of changing each element to the query value
    for i in range(M):
        query = int(input())
        cost[query] = 0
        for j in range(N):
            current = int(input())
            if current < query:
                cost[query] += abs(query - current)
            elif current > query:
                cost[query] += abs(query - current)
    # Return the total cost of all operations
    return cost
```

