import math

def hexCorner(center, size, index):
    angleDeg = 60 * index
    angleRad = math.radians(angleDeg)
    return (center[0] + size * math.cos(angleRad), center[1] + size * math.sin(angleRad))

def axialToPixel(q, r, size):
    x = size * (math.sqrt(3) * q + math.sqrt(3) / 2 * r)
    y = size * (3 / 2 * r)
    return (x, y)

def pixelToAxial(x, y, size):
    q = (math.sqrt(3) / 3 * x - 1 / 3 * y) / size
    r = (2 / 3 * y) / size
    return (round(q), round(r))

def cubeToAxial(cubeCoord):
    return (cubeCoord[0], cubeCoord[2])

def axialToCube(axialCoord):
    x = axialCoord[0]
    z = axialCoord[1]
    y = -x - z
    return (x, y, z)

def cubeDistance(a, b):
    return (abs(a[0] - b[0]) + abs(a[1] - b[1]) + abs(a[2] - b[2])) // 2

def axialDistance(a, b):
    cubeA = axialToCube(a)
    cubeB = axialToCube(b)
    return cubeDistance(cubeA, cubeB)
