Here's a compact implementation of labyrinthGeneration.py using Prim's algorithm:

```python
import random

def createEmptyGrid(width, height):
    return [[0 for x in range(width)] for y in range(height)]

def getNeighbors(grid, pos, visited):
    x, y = pos
    neighbors = []
    for dx, dy in [(-2, 0), (2, 0), (0, -2), (0, 2)]:
        nx, ny = x + dx, y + dy
        if 0 <= nx < len(grid[0]) and 0 <= ny < len(grid) and (nx, ny) not in visited:
            neighbors.append(((nx, ny), (x + dx // 2, y + dy // 2)))
    return neighbors

def primsAlgorithm(grid, start):
    visited = {start}
    stack = [start]
    while stack:
        current = stack.pop()
        neighbors = getNeighbors(grid, current, visited)
        if neighbors:
            nextCell, wall = random.choice(neighbors)
            grid[wall[1]][wall[0]] = 1
            visited.add(nextCell)
            stack.append(current)
            stack.append(nextCell)

def generateLabyrinth(width, height, start=(1, 1)):
    grid = createEmptyGrid(width, height)
    for y in range(height):
        for x in range(width):
            grid[y][x] = 1 if (x % 2 == 0 or y % 2 == 0) else 0
    primsAlgorithm(grid, start)
    return grid
```

