        self.draw()

    def draw(self):
        self.canvas.delete("all")
        for row in range(self.rows):
            for col in range(self.cols):
                if self.state[row][col]:
                    fillColor = "#228B22"
                else:
                    fillColor = "#F0E68C"
                self.canvas.create_rectangle(col * self.cellSize, row * self.cellSize, (col + 1) * self.cellSize, (row + 1) * self.cellSize, fill=fillColor, outline="#C0C0C0")

    def toggleCell(self, x, y):
        row = y // self.cellSize
        col = x // self.cellSize
        self.state[row][col] = not self.state[row][col]
        self.draw()

    def randomState(self, probability):
        return random.random() < probability

    def setZoom(self, newCellSize):
        self.cellSize = newCellSize
        self.canvas.config(width=self.cols * newCellSize, height=self.rows * newCellSize)
        self.draw()

    def clearBoard(self):
        self.state = [[False] * self.cols for row in range(self.rows)]
        self.draw()

    def loadPattern(self, pattern, rowOffset, colOffset):
        for row, rowContent in enumerate(pattern):
            for col, cell in enumerate(rowContent):
                self.state[row + rowOffset][col + colOffset] = cell
        self.draw()

    def toggleWrapEdges(self):
        self.wrapEdges = not self.wrapEdges

    def saveBoardState(self, fileName):
        with open(fileName, "w") as f:
            for row in self.state:
                f.write("".join(["1" if cell else "0" for cell in row]) + "\n")

    def loadBoardState(self, fileName):
        with open(fileName, "r") as f:
            loadedState = [list(map(lambda x: x == "1", line.strip())) for line in f]
        if len(loadedState) == self.rows and len(loadedState[0]) == self.cols:
            self.state = loadedState
            self.draw()

    def resizeBoard(self, newRows, newCols):
        if newRows > self.rows:
            for _ in range(newRows - self.rows):
                self.state.append([False] * self.cols)
        else:
            self.state = self.state[:newRows]

        if newCols > self.cols:
            for row in self.state:
                row.extend([False] * (newCols - self.cols))
        else:
            for row in self.state:
                row[:] = row[:newCols]

        self.rows = newRows
        self.cols = newCols

        self.canvas.config(width=self.cols * self.cellSize, height=self.rows * self.cellSize)
        self.draw()
