    // Send message to process i
  }

  public NAME_6 receiveMessage(int i) {
    // Receive message from process i
    return msg; 
  }

  public void exitCS() {
    // Send RELEASE to processes that sent ACK
    for (int i = 0; i < N; i++) {
      if (ACK[i] == 1) {
        sendMessage(i, "RELEASE");
        ACK[i] = 0;
      }
    }
  }
