typedef struct {
    unsigned char *tiles;
    unsigned int size;
    unsigned int used;
} PPU_TileCache;

// Initialize the PPU tile cache
void ppu_tile_cache_init(PPU_TileCache *cache) {
    cache->tiles = malloc(PPU_TILE_CACHE_SIZE * sizeof(unsigned char));
    cache->size = PPU_TILE_CACHE_SIZE;
    cache->used = 0;
}

// Clear the PPU tile cache
void ppu_tile_cache_clear(PPU_TileCache *cache) {
    cache->used = 0;
}

// Get a tile from the PPU tile cache
unsigned char *ppu_tile_cache_get(PPU_TileCache *cache, int tx, int ty) {
    // Check if the tile is in the cache
    if (tx >= 0 && tx < PPU_TILE_CACHE_SIZE && ty >= 0 && ty < PPU_TILE_CACHE_SIZE) {
        // Check if the tile is already in the cache
        if (cache->tiles[tx][ty]!= 0) {
            // Update the used tile counter
            cache->used++;
            return &cache->tiles[tx][ty];
        }
    }

    // Add the tile to the cache
    if (cache->used == PPU_TILE_CACHE_SIZE) {
        // Resize the cache if necessary
        if (cache->size < PPU_TILE_CACHE_SIZE * 2) {
            cache->size *= 2;
            cache->tiles = realloc(cache->tiles, cache->size * sizeof(unsigned char));
        }
    }

    // Set the tile in the cache
    cache->tiles[tx][ty] = 1;
    return &cache->tiles[tx][ty];
