from flask import Flask, request, jsonify
import jwt
import datetime

app = Flask(__name__)
app.config["SECRET_KEY"] = "your_secret_key"

@app.route("/login", methods=["POST"])
def login():
    username = request.json.get("username")
    password = request.json.get("password")

    user = authenticate(username, password)

    if user:
        token = create_token(user)
        return jsonify({"token": token})
    else:
        return jsonify({"error": "Invalid credentials"})

def authenticate(username, password):
    user = authenticated_user(username, password)
    if user:
        return user
    else:
        return None

def create_token(user):
    payload = {
        "sub": user["username"],
        "exp": datetime.datetime.utcnow() + datetime.timedelta(minutes=30),
        "iat": datetime.datetime.utcnow()
    }

    token = jwt.encode(payload, app.config["SECRET_KEY"], algorithm="HS256")
    return token

@app.route("/user_info", methods=["GET"])
def user_info():
    token = request.headers.get("Authorization")
    if not token:
        return jsonify({"error": "No token provided"})

    try:
        token_info = jwt.decode(token, app.config["SECRET_KEY"], algorithms=["HS256"])
        user = token_info["sub"]
        return jsonify(authenticated_user(user))
    except:
        return jsonify({"error": "Invalid token"})

def authenticated_user(username, password):
    user = User.query.filter_by(username=username).first()
    if user and user.password == password:
        return user
    else:
        return None
