import numpy as np

def sherman_morrison_inversion(A, y, X):
    """
    Returns the solution to the system of linear equations represented by A, given a right-hand side vector y and a matrix X.

    Args:
    A (np.ndarray): a (2, N) matrix representing the system of linear equations.
    y (np.ndarray): a (2, 1) vector representing the right-hand side.
    X (np.ndarray): a (N, 2) matrix representing the matrix of coefficients.

    Returns:
    np.ndarray: a (1, 2) solution vector.
    """
    if X.shape[1] != A.shape[1]:
        raise ValueError("X and A must have the same number of columns")

    if X.shape[1] == 1:
        return X[0]

    if A.shape[1] == 1:
        return X[1]

    if X[1, 1] != 0:
        return np.dot(X[1, 1], np.dot(X[1, :A.shape[1]], A.dot(X[1, 1], y)))
    else:
        return np.dot(X[1, :A.shape[1]], A.dot(X[1, 1], y))

