                            return d
                        elif check_sudoku(d, n, solved):
                            return d

    # no solution found
    return None

def add_candidate(d, i, j, num):
    if i < 1 or i > n or j < 1 or j > n or d[i][j] != '.':
        return False
    for k in range(1, n):
        if d[i][k] == num:
            return False
    for k in range(1, n):
        if d[k][j] == num:
            return False
    d[i][j] = num
    return True

def check_sudoku(d, n, solved):
    for i in range(1, n):
        for j in range(1, n):
            if d[i][j] == '.':
                if all(k != i and k != j for k in solved):
                    return False
    return True

