    # Base case: If n = 0, there is only one queen, and it does not attack any other queen
    if n == 0:
        return [[]]

    # Create a list of all possible positions for the queens
    possible_positions = []
    for row in range(n):
        possible_positions.append([row])

    # Backtracking algorithm: Try each possible position and recursively explore all possible positions for the remaining queens
    solutions = []
    for position in possible_positions:
        current_queen = [row]
        for i in range(n - 1):
            # Try each possible position for the next queen, making sure it does not attack any other queen
