                        break
            else:
                # If no attack is found, add the current queen to the solution and recursively explore all possible positions for the remaining queens
                solutions.append(current_queen + [row])
                solve_n_queens(n - 1, position, row)

    return solutions

def check_attack(position, row):
    # Check if the current queen attacks any other queen
    for i in range(n):
        if i != row and position[i]:
            return True
    return False

